/* Авторские задачи пробника ОГЭ-2027. */
(() => {
  function block(n) {
    return `Для обновления школьного двора отвели прямоугольник ${20+n} м на 16 м. Вдоль одной короткой стороны выделили полосу шириной 3 м по всей длине этой стороны. На остальной площадке укладывают покрытие по ${100+10*n} рублей за квадратный метр. План выполнен без масштаба.`;
  }
  function diagram(caption, coordinates, edges) {
    return {geometry:{caption,
      points:coordinates.map(([id,x,y,label])=>({id,x,y,label:label ?? id})),
      segments:edges.map(([from,to])=>({from,to}))
    }};
  }
  const plan = diagram('План двора. Полоса расположена слева.',[
    ['A',60,60,''],['B',560,60,''],['C',560,240,''],['D',60,240,''],
    ['E',130,60,''],['F',130,240,''],['G',80,270,'полоса']
  ],[['A','B'],['B','C'],['C','D'],['D','A'],['E','F']]);
  const triangle = diagram('Прямой угол при C. Схема без масштаба.',[
    ['A',110,245],['B',410,65],['C',410,245],['D',390,245,''],['E',390,225,''],['F',410,225,'']
  ],[['A','C'],['B','C'],['A','B'],['D','E'],['E','F']]);
  const rectangle = diagram('Прямоугольник ABCD. Схема без масштаба.',[
    ['A',90,240],['B',490,240],['C',490,65],['D',90,65],['O',290,152]
  ],[['A','B'],['B','C'],['C','D'],['D','A'],['A','C'],['B','D']]);
  const trapezoid = diagram('Трапеция с основаниями AD и BC. Схема без масштаба.',[
    ['A',80,240],['B',220,70],['C',400,70],['D',540,240]
  ],[['A','B'],['B','C'],['C','D'],['D','A']]);

  const circle = {geometry:{
    caption:'Радиусы OA и OB образуют прямой угол. Схема без масштаба.',
    circles:[{cx:310,cy:155,r:100}],
    points:[{id:'O',x:310,y:155,label:'O'},{id:'A',x:410,y:155,label:'A'},{id:'B',x:310,y:55,label:'B'}],
    segments:[{from:'O',to:'A'},{from:'O',to:'B'},{from:'A',to:'B'}]
  }};

  const templates = [
    ['Площадь двора', n=>['Найди площадь всего двора в квадратных метрах.',16*(20+n),`Умножь длину на ширину: ${20+n}·16 = ${16*(20+n)} м².`]],
    ['Периметр двора', n=>['Найди периметр двора в метрах.',2*(36+n),`Периметр равен 2·(${20+n}+16) = ${2*(36+n)} м.`]],
    ['Площадь покрытия', n=>['Сколько квадратных метров займёт покрытие?',16*(17+n),`Из длины ${20+n} м вычитаем 3 м. Площадь покрытия равна ${17+n}·16 = ${16*(17+n)} м².`]],
    ['Стоимость покрытия', n=>['Сколько рублей будет стоить покрытие для всей отведённой под него площадки?',16*(17+n)*(100+10*n),`Площадь покрытия ${16*(17+n)} м². Умножаем на ${100+10*n} рублей и получаем ${16*(17+n)*(100+10*n)} рублей.`]],
    ['Изменение бюджета', n=>['Цена покрытия выросла на 10%. На сколько рублей увеличится стоимость покрытия всей площадки?',16*(17+n)*(10+n),`Доплата за 1 м² равна ${10+n} рублей. Доплата за всю площадь составляет ${16*(17+n)}·${10+n} = ${16*(17+n)*(10+n)} рублей.`]],
    ['Вычисления', n=>[`Вычисли ${n}/4 + ${n+2}/2.`,(3*n+4)/4,`Приводим к общему знаменателю 4. Получаем ${3*n+4}/4 = ${(3*n+4)/4}.`]],
    ['Числа на координатной прямой', n=>[`На рисунке отмечено число A. Какое из чисел больше A: 1) ${n-1}, 2) ${n}, 3) ${n+1}, 4) ${n-2}? Запиши номер ответа.`,3,`Точка A расположена на отметке ${n+0.5}. Из предложенных чисел больше неё только ${n+1}, это вариант 3.`,
      {range:[n-3,n+3,-1,1],xStep:.5,yStep:1,curves:[],points:[{x:n+.5,y:0,label:'A'}]}]],
    ['Степени и корни', n=>[`Вычисли √${9*n*n} / 3.`,n,`Квадратный корень равен ${3*n}, делим на 3 и получаем ${n}.`]],
    ['Уравнение', n=>[`Реши уравнение 4x − ${n} = ${3*n+8}.`,n+2,`Прибавляем ${n} к обеим частям: 4x = ${4*n+8}. Тогда x = ${n+2}.`]],
    ['Вероятность', n=>[`В коробке 25 шаров, из них ${n} белых. Наугад выбирают один шар. Какова вероятность, что он белый?`,n/25,`Число равновероятных исходов 25, благоприятных ${n}. Вероятность равна ${n}/25 = ${n/25}.`]],
    ['График функции', n=>[`На рисунке изображена прямая y = kx + b. Найди b.`,n,`Свободный член равен ординате точки пересечения прямой с осью y: b = ${n}.`,
      {range:[-4,4,0,35],xStep:1,yStep:2,curves:[{kind:'line',parameters:[1,n]}],points:[{x:0,y:n,label:'A'}]}]],
    ['Расчёт по формуле', n=>[`Длина окружности равна 2πr. Вычисли её при r = ${n} см, приняв π = 3,14. Ответ дай в сантиметрах.`,6.28*n,`Подставляем радиус: 2·3,14·${n} = ${Number((6.28*n).toFixed(2))} см.`]],
    ['Неравенство', n=>[`Какое число удовлетворяет неравенству 2x > ${2*n}? 1) ${n-1}, 2) ${n}, 3) ${n-2}, 4) ${n+2}. Запиши номер ответа.`,4,`После деления на 2 получаем x > ${n}. Подходит только число ${n+2}, это вариант 4.`]],
    ['Арифметическая прогрессия', n=>[`Первый член арифметической прогрессии равен ${n}, разность равна 3. Найди шестой член.`,n+15,`Шестой член: a₆ = a₁ + 5d = ${n}+15 = ${n+15}.`]],
    ['Треугольник', n=>[`Катеты прямоугольного треугольника ABC равны ${3*n} и ${4*n}. Найди длину гипотенузы.`,5*n,`По теореме Пифагора гипотенуза равна √((3n)²+(4n)²) при n = ${n}, то есть ${5*n}.`,triangle]],
    ['Окружность', n=>[`Радиус окружности с центром O равен ${n}. Точки A и B лежат на окружности, ∠AOB = 90°. Найди квадрат длины хорды AB.`,2*n*n,`Треугольник AOB прямоугольный. По теореме Пифагора AB² = ${n}² + ${n}² = ${2*n*n}.`,circle]],
    ['Четырёхугольник', n=>[`Стороны прямоугольника ABCD равны ${3*n} и ${4*n}. Найди длину диагонали AC.`,5*n,`Применяем теорему Пифагора к треугольнику ABC: AC = √((3n)²+(4n)²) = ${5*n} при n = ${n}.`,rectangle]],
    ['Фигура на клетчатой бумаге', n=>[`Найди площадь прямоугольного треугольника на координатной сетке. Площадь единичной клетки равна 1.`,2*n,`Длины катетов ${n} и 4. Площадь равна ${n}·4/2 = ${2*n}.`,
      {range:[-1,n+1,-1,5],xStep:1,yStep:1,curves:[],outline:[[0,0],[n,0],[0,4],[0,0]],vectors:[]}]],
    ['Геометрические утверждения', n=>{
      const statements=['У прямоугольника диагонали равны.','У любого ромба все углы прямые.','У равнобедренного треугольника углы при основании равны.'];
      const order=[0,1,2].map(i=>(i+n)%3);
      const answer=Number(order.map((item,i)=>item===1?'':String(i+1)).join(''));
      return [`Запиши номера верных утверждений в порядке возрастания без разделителей. ${order.map((id,i)=>(i+1)+') '+statements[id]).join(' ')}`,answer,
        `Равенство диагоналей прямоугольника и равенство углов при основании верны. Среди ромбов прямые углы есть только у квадрата. Ответ: ${answer}.`];
    }],
    ['Алгебраическое уравнение', n=>[`Реши уравнение x² − ${2*n+3}x + ${n*(n+3)} = 0. Запиши решение.`,null,`По теореме Виета корни имеют сумму ${2*n+3} и произведение ${n*(n+3)}. Разложение (x − ${n})(x − ${n+3}) = 0 даёт корни ${n} и ${n+3}.`]],
    ['Текстовая задача', n=>[`Два школьника одновременно вышли навстречу друг другу из пунктов, между которыми ${150*n} м. Первый идёт на 10 м/мин быстрее второго. Через ${n} мин они встретились. Найди скорости обоих в м/мин.`,null,`Пусть v — скорость второго. За ${n} мин они проходят ${n}(v + v + 10) = ${150*n} м. Получаем 2v + 10 = 150, откуда скорости 70 и 80 м/мин.`]],
    ['Построение графика', n=>[`Опиши построение графика y = (x − ${n})² − 4. Укажи вершину и все значения m, при которых прямая y = m пересекает график в двух точках.`,null,`Сдвинь параболу y=x² на ${n} вправо и на 4 вниз. Вершина (${n}; −4); ветви направлены вверх. Две точки пересечения получаются при m > −4.`]],
    ['Геометрическая задача на вычисление', n=>[`Основания равнобедренной трапеции равны ${8*n} и ${2*n}, боковые стороны равны ${5*n}. Найди площадь и обоснуй ответ.`,null,`Половина разности оснований равна ${3*n}. Высота равна √((5n)²−(3n)²) = ${4*n} при n = ${n}. Площадь равна (${8*n}+${2*n})·${4*n}/2 = ${20*n*n}.`,trapezoid]],
    ['Доказательство', n=>[`В прямоугольнике ABCD диагонали пересекаются в O. Известно, что AC = ${2*n}. Докажи, что OA = OB, и найди их длины.`,null,`Диагонали прямоугольника равны и точкой пересечения делятся пополам. Следовательно, OA = AC/2 = BD/2 = OB = ${n}.`,rectangle]],
    ['Геометрия повышенной сложности', n=>[`В прямоугольном треугольнике ABC с прямым углом C катеты AC и BC равны ${3*n} и ${4*n}. На гипотенузу опущена высота CH. Найди CH и AH, обосновав оба результата.`,null,`Гипотенуза AB = ${5*n}. Выразим площадь двумя способами: AC·BC = AB·CH, так что CH = ${2.4*n}. Из подобия ABC и ACH следует AC² = AB·AH. Тогда AH = ${1.8*n}.`,triangle]]
  ];

  const card = document.createElement('section');
  const heading = document.createElement('h3');
  const description = document.createElement('p');
  heading.textContent = 'Общее условие к заданиям 1–5';
  card.className = 'exam-shared-statement';
  card.append(heading, description);
  card.insertAdjacentHTML('beforeend', egeFigure({id:'oge-yard-plan',title:'План двора',question:'План двора',figure:plan}));
  document.getElementById('ogeVariantShort').before(card);

  window.mountMathExam({
    key:'oge', templates, shortCount:19, sharedCount:5,
    renderShared: seed => { description.textContent = block(seed); }
  });
})();

